UPDATE shopping_cart
SET vessel_call_id = #{vesselCallId},
    update_time    = NOW()
WHERE tenant_id = #{tenantId}
  AND vessel_id = #{vesselId}
  AND del_flag = '0'
  AND (vessel_call_id IS NULL OR vessel_call_id = ''


        OR vessel_call_id = #{stale}


  )

